Lemma rd_be_8 p pos : 0 <= pos -> pos + 8 <= blen p ->
  rd_be p pos 8 = bat p pos * 2 ^ 56 + bat p (pos + 1) * 2 ^ 48 + bat p (pos + 1 + 1) * 2 ^ 40 + bat p (pos + 1 + 1 + 1) * 2 ^ 32
                  + bat p (pos + 1 + 1 + 1 + 1) * 2 ^ 24 + bat p (pos + 1 + 1 + 1 + 1 + 1) * 2 ^ 16 + bat p (pos + 1 + 1 + 1 + 1 + 1 + 1) * 2 ^ 8
