Lemma sgn_cases k b rest : (k = 1 \/ k = 2 \/ k = 4 \/ k = 8) -> 0 <= b < 256 -> 0 <= rest < 2 ^ (8 * k - 8) ->
  (sgn k (b * 2 ^ (8 * k - 8) + rest) <? 0) = (128 <=? b)
  /\ (b < 128 -> sgn k (b * 2 ^ (8 * k - 8) + rest) = b * 2 ^ (8 * k - 8) + rest).
